function DecryptAES {
    param (
        [string]$encryptedHexString,
        [string]$key
    )
    
    $encryptedHexString = $encryptedHexString -replace '\s+', ''

    if ($encryptedHexString.Length % 2 -ne 0) {
        throw "Invalid hex string length"
    }

    function Convert-HexToBytes {
        param ([string]$hexString)

        $bytes = New-Object byte[] ($hexString.Length / 2)
        for ($i = 0; $i -lt $hexString.Length; $i += 2) {
            $bytes[$i / 2] = [Convert]::ToByte($hexString.Substring($i, 2), 16)
        }
        return $bytes
    }

    $encryptedData = Convert-HexToBytes $encryptedHexString
    $iv = $encryptedData[0..15]
    $encryptedBytes = $encryptedData[16..($encryptedData.Length - 1)]
    $keyBytes = [System.Text.Encoding]::UTF8.GetBytes($key)[0..15]

    $aesAlg = [System.Security.Cryptography.AesManaged]::new()
    $aesAlg.Key = $keyBytes
    $aesAlg.IV  = $iv
    $aesAlg.Mode = [System.Security.Cryptography.CipherMode]::CBC
    $aesAlg.Padding = [System.Security.Cryptography.PaddingMode]::PKCS7

    $decryptor = $aesAlg.CreateDecryptor()
    $decryptedBytes = $decryptor.TransformFinalBlock(
        $encryptedBytes,
        0,
        $encryptedBytes.Length
    )

    return [System.Text.Encoding]::UTF8.GetString($decryptedBytes)
}


