function Compile-AndExecute {
    param (
        [string]$csharpCode,
        [string]$methodName,
        [string[]]$parameters
    )

    $provider = New-Object Microsoft.CSharp.CSharpCodeProvider

    $parametersCompile = New-Object System.CodeDom.Compiler.CompilerParameters
    $parametersCompile.GenerateInMemory = $true
    $parametersCompile.GenerateExecutable = $false
    $parametersCompile.ReferencedAssemblies.Add("System.dll")
    $parametersCompile.ReferencedAssemblies.Add("System.Windows.Forms.dll")

    $compileResults = $provider.CompileAssemblyFromSource($parametersCompile, $csharpCode)

    if ($compileResults.Errors.HasErrors) {
        throw "Compilation failed: $($compileResults.Errors)"
    }

    $assembly = $compileResults.CompiledAssembly

    $type = $assembly.GetType("DynamicNamespace.DynamicClass")
    $method = $type.GetMethod($methodName)

    return $method.Invoke($null, $parameters)
}

